package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w360dp-h800dp-mdpi") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class BibleImportUi5180Test{
 ActivityController<ToolsActivity> controller;ToolsActivity a;
 @Before public void before()throws Exception{new FlashDesignTest().before();controller=Robolectric.buildActivity(ToolsActivity.class);a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);controller.create().start().resume().visible();}
 @After public void close(){controller.pause().stop().destroy();}
 @Test public void usxFolderPickerUsesAndroidTreeAndKeepsTranslationNameAcrossRotation()throws Exception{a.pickUsxFolder();UiDialog dialog=(UiDialog)ShadowDialog.getLatestDialog();assertTrue(BooksToolsTest.labels(dialog.root).contains("USX_1"));new ReferenceDesign5150Test().capture(dialog.root,"importar-usx-5180",336,460);dialog.getButton(DialogInterface.BUTTON_POSITIVE).performClick();ShadowActivity.IntentForResult result=shadowOf(a).getNextStartedActivityForResult();assertEquals(Intent.ACTION_OPEN_DOCUMENT_TREE,result.intent.getAction());assertEquals(ToolsActivity.BIBLE_USX_FOLDER,result.requestCode);assertTrue((result.intent.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0);Bundle state=new Bundle();a.onSaveInstanceState(state);assertEquals("Minha Bíblia USX",state.getString("bible_title"));}
 @Test public void myBiblePickerAllowsGenericBinMime()throws Exception{a.pickBible("ARA");UiDialog dialog=(UiDialog)ShadowDialog.getLatestDialog();dialog.getButton(DialogInterface.BUTTON_POSITIVE).performClick();ShadowActivity.IntentForResult result=shadowOf(a).getNextStartedActivityForResult();assertEquals(Intent.ACTION_OPEN_DOCUMENT,result.intent.getAction());assertEquals("*/*",result.intent.getType());assertEquals(ToolsActivity.BIBLE,result.requestCode);assertEquals("ARA",a.bibleTitle);}
}
